-- NETS Merchant Portal: full schema for `SOI-2026-0021-sherwin`
-- Generated by scripts/export-schema.mjs from db/migrations (0001_core.sql, 0002_auth.sql, 0003_invoice_line_channel.sql, 0004_recon_exception_detail.sql, 0005_recon_checked_count.sql, 0006_kb.sql).
-- Do not edit by hand: change a migration and regenerate.
-- Needs MySQL 8.0 (InnoDB, utf8mb4). Contains no data and no users.

SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS `SOI-2026-0021-sherwin` CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE `SOI-2026-0021-sherwin`;

-- ===== 0001_core.sql =====
-- Child tables use composite foreign keys (id, merchant_id) so a child can never point at
-- another merchant's parent row.
-- Core merchant data. InnoDB, utf8mb4, ids CHAR(36), money BIGINT cents, times DATETIME(3) UTC.

CREATE TABLE merchants (
  id             CHAR(36)     NOT NULL,
  legal_name     VARCHAR(200) NOT NULL,
  trading_name   VARCHAR(200) NOT NULL,
  uen            VARCHAR(20)  NOT NULL,
  category       VARCHAR(60)  NOT NULL,
  gst_registered TINYINT(1)   NOT NULL DEFAULT 0,
  created_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE outlets (
  id          CHAR(36)     NOT NULL,
  merchant_id CHAR(36)     NOT NULL,
  name        VARCHAR(200) NOT NULL,
  address     VARCHAR(300) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_outlets_id_merchant (id, merchant_id),
  KEY idx_outlets_merchant (merchant_id),
  CONSTRAINT fk_outlets_merchant FOREIGN KEY (merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE terminals (
  id          CHAR(36)    NOT NULL,
  merchant_id CHAR(36)    NOT NULL,
  outlet_id   CHAR(36)    NOT NULL,
  serial_no   VARCHAR(60) NOT NULL,
  model       VARCHAR(60) NULL,
  status      VARCHAR(20) NOT NULL DEFAULT 'active',
  PRIMARY KEY (id),
  UNIQUE KEY uq_terminals_id_merchant (id, merchant_id),
  KEY idx_terminals_merchant (merchant_id),
  KEY idx_terminals_outlet (outlet_id, merchant_id),
  CONSTRAINT fk_terminals_merchant FOREIGN KEY (merchant_id) REFERENCES merchants (id) ON DELETE CASCADE,
  CONSTRAINT fk_terminals_outlet FOREIGN KEY (outlet_id, merchant_id) REFERENCES outlets (id, merchant_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE settlements (
  id            CHAR(36)    NOT NULL,
  merchant_id   CHAR(36)    NOT NULL,
  business_date DATE        NOT NULL,
  channel       ENUM('nets_qr','nets_click','enets','card','sgqr') NOT NULL,
  gross_cents   BIGINT      NOT NULL,
  fee_cents     BIGINT      NOT NULL,
  net_cents     BIGINT      NOT NULL,
  status        ENUM('pending','paid','delayed') NOT NULL DEFAULT 'pending',
  expected_date DATE        NULL,
  paid_date     DATE        NULL,
  bank_ref      VARCHAR(60) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_settlements_id_merchant (id, merchant_id),
  KEY idx_settlements_merchant_date (merchant_id, business_date),
  CONSTRAINT fk_settlements_merchant FOREIGN KEY (merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE transactions (
  id            CHAR(36)    NOT NULL,
  merchant_id   CHAR(36)    NOT NULL,
  outlet_id     CHAR(36)    NULL,
  terminal_id   CHAR(36)    NULL,
  channel       ENUM('nets_qr','nets_click','enets','card','sgqr') NOT NULL,
  status        ENUM('success','failed','refunded') NOT NULL,
  amount_cents  BIGINT      NOT NULL,
  fee_cents     BIGINT      NOT NULL DEFAULT 0,
  customer_ref  VARCHAR(64) NULL,
  failure_code  VARCHAR(40) NULL,
  settlement_id CHAR(36)    NULL,
  created_at    DATETIME(3) NOT NULL,
  PRIMARY KEY (id),
  KEY idx_txn_merchant_created (merchant_id, created_at),
  KEY idx_txn_merchant_status_created (merchant_id, status, created_at),
  KEY idx_txn_outlet (outlet_id, merchant_id),
  KEY idx_txn_terminal (terminal_id, merchant_id),
  KEY idx_txn_settlement (settlement_id, merchant_id),
  CONSTRAINT fk_txn_merchant FOREIGN KEY (merchant_id) REFERENCES merchants (id) ON DELETE CASCADE,
  CONSTRAINT fk_txn_outlet FOREIGN KEY (outlet_id, merchant_id) REFERENCES outlets (id, merchant_id) ON DELETE CASCADE,
  CONSTRAINT fk_txn_terminal FOREIGN KEY (terminal_id, merchant_id) REFERENCES terminals (id, merchant_id) ON DELETE CASCADE,
  CONSTRAINT fk_txn_settlement FOREIGN KEY (settlement_id, merchant_id) REFERENCES settlements (id, merchant_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE invoices (
  id          CHAR(36)     NOT NULL,
  merchant_id CHAR(36)     NOT NULL,
  period      DATE         NOT NULL COMMENT 'first day of the billed month',
  total_cents BIGINT       NOT NULL,
  status      ENUM('unpaid','paid','overdue') NOT NULL DEFAULT 'unpaid',
  due_date    DATE         NOT NULL,
  pdf_path    VARCHAR(300) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_invoices_id_merchant (id, merchant_id),
  KEY idx_invoices_merchant_period (merchant_id, period),
  CONSTRAINT fk_invoices_merchant FOREIGN KEY (merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE invoice_lines (
  id               CHAR(36)     NOT NULL,
  merchant_id      CHAR(36)     NOT NULL,
  invoice_id       CHAR(36)     NOT NULL,
  charge_type      VARCHAR(40)  NOT NULL,
  description      VARCHAR(200) NOT NULL,
  qty              INT          NOT NULL DEFAULT 1,
  unit_price_cents BIGINT       NULL,
  amount_cents     BIGINT       NOT NULL,
  PRIMARY KEY (id),
  KEY idx_invoice_lines_merchant (merchant_id),
  KEY idx_invoice_lines_invoice (invoice_id, merchant_id),
  CONSTRAINT fk_invoice_lines_merchant FOREIGN KEY (merchant_id) REFERENCES merchants (id) ON DELETE CASCADE,
  CONSTRAINT fk_invoice_lines_invoice FOREIGN KEY (invoice_id, merchant_id) REFERENCES invoices (id, merchant_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE recon_runs (
  id              CHAR(36)    NOT NULL,
  merchant_id     CHAR(36)    NOT NULL,
  period          DATE        NOT NULL,
  run_at          DATETIME(3) NOT NULL,
  matched_count   INT         NOT NULL DEFAULT 0,
  exception_count INT         NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uq_recon_runs_id_merchant (id, merchant_id),
  KEY idx_recon_runs_merchant (merchant_id, run_at),
  CONSTRAINT fk_recon_runs_merchant FOREIGN KEY (merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE recon_exceptions (
  id             CHAR(36)     NOT NULL,
  merchant_id    CHAR(36)     NOT NULL,
  run_id         CHAR(36)     NOT NULL,
  type           ENUM('amount_mismatch','missing_settlement','settlement_delay','failed_payment','fee_mismatch') NOT NULL,
  settlement_id  CHAR(36)     NULL,
  transaction_id CHAR(36)     NULL,
  expected_cents BIGINT       NULL,
  actual_cents   BIGINT       NULL,
  status         ENUM('open','resolved') NOT NULL DEFAULT 'open',
  note           VARCHAR(500) NULL,
  PRIMARY KEY (id),
  KEY idx_recon_exc_merchant_status (merchant_id, status),
  KEY idx_recon_exc_run (run_id, merchant_id),
  CONSTRAINT fk_recon_exc_merchant FOREIGN KEY (merchant_id) REFERENCES merchants (id) ON DELETE CASCADE,
  CONSTRAINT fk_recon_exc_run FOREIGN KEY (run_id, merchant_id) REFERENCES recon_runs (id, merchant_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE notifications (
  id          CHAR(36)     NOT NULL,
  merchant_id CHAR(36)     NOT NULL,
  kind        VARCHAR(40)  NOT NULL,
  title       VARCHAR(200) NOT NULL,
  body        VARCHAR(500) NULL,
  link        VARCHAR(300) NULL,
  created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  read_at     DATETIME(3)  NULL,
  PRIMARY KEY (id),
  KEY idx_notifications_merchant (merchant_id, created_at),
  CONSTRAINT fk_notifications_merchant FOREIGN KEY (merchant_id) REFERENCES merchants (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===== 0002_auth.sql =====
-- Login: users, server-side sessions, and which merchants a user may see.

CREATE TABLE users (
  id            CHAR(36)     NOT NULL,
  email         VARCHAR(254) NOT NULL,
  password_hash VARCHAR(100) NOT NULL,
  name          VARCHAR(120) NOT NULL,
  created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_login_at DATETIME(3)  NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE sessions (
  id         CHAR(36)    NOT NULL,
  user_id    CHAR(36)    NOT NULL,
  token_hash CHAR(64)    NOT NULL COMMENT 'SHA-256 of the cookie token',
  expires_at DATETIME(3) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_sessions_token (token_hash),
  KEY idx_sessions_user (user_id),
  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE merchant_users (
  merchant_id CHAR(36) NOT NULL,
  user_id     CHAR(36) NOT NULL,
  role        ENUM('owner','manager','cashier','accountant') NOT NULL,
  PRIMARY KEY (merchant_id, user_id),
  KEY idx_merchant_users_user (user_id),
  CONSTRAINT fk_mu_merchant FOREIGN KEY (merchant_id) REFERENCES merchants (id) ON DELETE CASCADE,
  CONSTRAINT fk_mu_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===== 0003_invoice_line_channel.sql =====
-- Which payment channel an MDR invoice line belongs to (NULL for terminal rental / portal fee).
ALTER TABLE invoice_lines
  ADD COLUMN channel ENUM('nets_qr','nets_click','enets','card','sgqr') NULL AFTER charge_type;

-- ===== 0004_recon_exception_detail.sql =====
-- What a check-up problem is about, so the page can show it without re-running the check.
-- `message` is the plain-English sentence; `day` and `channel` say which sales it concerns.
-- (`note` stays the merchant's own words from "Mark as sorted".)
ALTER TABLE recon_exceptions
  ADD COLUMN day DATE NULL AFTER transaction_id,
  ADD COLUMN channel ENUM('nets_qr','nets_click','enets','card','sgqr') NULL AFTER day,
  ADD COLUMN message VARCHAR(300) NULL AFTER channel;

-- ===== 0005_recon_checked_count.sql =====
-- How many items a check-up looked at (settlements, bill lines and missing days), so the page shows it without re-deriving it.
ALTER TABLE recon_runs
  ADD COLUMN checked_count INT NOT NULL DEFAULT 0 AFTER matched_count;

-- ===== 0006_kb.sql =====
-- Help-centre passages for the NETS Assistant. Shared content, NOT merchant data: no merchant_id.
-- Seeded from content/faq.md by `npm run seed`. Full-text search for the MVP (embeddings are Phase 2).

CREATE TABLE kb_chunks (
  id      INT          NOT NULL AUTO_INCREMENT,
  source  VARCHAR(80)  NOT NULL COMMENT 'topic group, e.g. Settlements',
  heading VARCHAR(200) NOT NULL COMMENT 'the question',
  content TEXT         NOT NULL COMMENT 'the answer',
  PRIMARY KEY (id),
  FULLTEXT KEY ft_kb_chunks (heading, content)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===== migration bookkeeping (so `npm run migrate` skips these files) =====
CREATE TABLE IF NOT EXISTS schema_migrations (
  name VARCHAR(200) NOT NULL PRIMARY KEY,
  applied_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB;
INSERT IGNORE INTO schema_migrations (name) VALUES
  ('0001_core.sql'),
  ('0002_auth.sql'),
  ('0003_invoice_line_channel.sql'),
  ('0004_recon_exception_detail.sql'),
  ('0005_recon_checked_count.sql'),
  ('0006_kb.sql');
